const palette=['#287c78','#bf8d48','#8765a1','#637fa3'];
function histogram(values,bins=16,lo=0,hi=255){const counts=Array(bins).fill(0);let n=0;for(const v of values)if(Number.isFinite(v)){counts[Math.max(0,Math.min(bins-1,Math.floor((v-lo)/(hi-lo)*bins)))]++;n++;}return{counts,n,lo,hi};}
