function series(points,xLabel,yLabel,{color=palette[0],width=700,height=260,log=false}={}){const valid=points.filter(p=>Number.isFinite(p[0])&&Number.isFinite(p[1])&&(!log||p[1]>0)),xx=valid.map(p=>p[0]),yy=valid.map(p=>log?Math.log10(p[1]):p[1]);if(!valid.length)return '<p>没有适用的正值。</p>';const lo=Math.min(...xx),hi=Math.max(...xx),bottom=Math.min(...yy),top=Math.max(...yy),x=v=>65+(v-lo)/Math.max(1e-9,hi-lo)*(width-95),y=v=>height-60-(v-bottom)/Math.max(1e-9,top-bottom)*(height-95);return `<svg viewBox="0 0 ${width} ${height}" role="img" aria-label="${xLabel}与${yLabel}"><path d="M65 20V${height-60}H${width-25}" stroke="#97ac9c" fill="none"/><path d="${valid.map((p,i)=>(i?'L':'M')+x(p[0])+' '+y(log?Math.log10(p[1]):p[1])).join('')}" stroke="${color}" fill="none" stroke-width="1.8"/><g font-size="12" fill="#365144"><text x="65" y="${height-40}">${lo.toFixed(2)}</text><text x="${width-85}" y="${height-40}">${hi.toFixed(2)}</text><text x="240" y="${height-15}">${xLabel}</text><text x="5" y="15">${log?'log10 ':''}${yLabel} ${bottom.toFixed(2)}–${top.toFixed(2)}</text></g></svg>`;}
function depthSeries(groups,depthLabel,opts={}){const depths=groups.flatMap(a=>a.points.map(p=>p[0])).filter(Number.isFinite),lo=Math.min(...depths),hi=Math.max(...depths),y=d=>45+(d-lo)/Math.max(1e-9,hi-lo)*355,track=580/groups.length;let html='<svg viewBox="0 0 700 470" role="img" aria-label="深度向下的实测曲线"><g font-size="12" fill="#365144">';for(let j=0;j<5;j++){const d=lo+(hi-lo)*j/4;html+='<path d="M65 '+y(d)+'H670" stroke="#d9e2d5"/><text x="5" y="'+(y(d)+4)+'">'+d.toFixed(2)+'</text>';}groups.forEach((a,i)=>{const good=a.points.filter(p=>Number.isFinite(p[1])&&(!a.log||p[1]>0)),vals=good.map(p=>a.log?Math.log10(p[1]):p[1]),min=Math.min(...vals),max=Math.max(...vals),x=v=>75+i*track+(v-min)/Math.max(1e-9,max-min)*(track-35);let d='',pen=false;for(const p of a.points){if(!Number.isFinite(p[1])||a.log&&p[1]<=0){pen=false;continue;}d+=(pen?'L':'M')+x(a.log?Math.log10(p[1]):p[1])+' '+y(p[0]);pen=true;}html+='<text x="'+(75+i*track)+'" y="20">'+(a.log?'log10 ':'')+a.name+'</text><path d="'+d+'" fill="none" stroke="'+palette[i%4]+'" stroke-width="1.8"/><text x="'+(75+i*track)+'" y="425">'+min.toFixed(2)+' → '+max.toFixed(2)+'</text>';});for(const d of opts.boundaries??[])html+='<path d="M65 '+y(d)+'H670" stroke="#ad693f" stroke-dasharray="3 3" opacity=".45"/>';return html+'<text x="220" y="453">'+depthLabel+'；深度向下增加 ↓</text></g></svg>';}
function panel(id,title,after){let p=document.getElementById(id);if(!p){p=document.createElement('article');p.id=id;p.className='panel';p.innerHTML=`<h2>${title}</h2><div class="enhanced-body"></div>`;const target=document.getElementById(after);(target?.closest('article')??target??document.getElementById('lab')).insertAdjacentElement('afterend',p);}return p.querySelector('.enhanced-body');}
