function apply(lesson,scene){
 if(scene==='m1')lesson.background[0].svg=circulation();
 if(scene==='m2'){lesson.background[1].html=gasContext();lesson.background[1].caption='接单根和起钻均可能伴随停泵及抽吸影响；气体随后随循环返出。图示只解释关联机制，不给出井控决策。专业依据为SLB connection gas / trip gas；固定气峰改工况的反事实没有评价金标。';}
 if(scene==='m3')lesson.background[0].svg=pair();
 if(scene==='m4')lesson.background[1].svg=drill();
 if(scene==='m5')lesson.background[1].svg=wording();
}
